/**
 * O voo do albatroz — o alongamento AR = b²/S, desenhado como asa e como planeio.
 *
 * `b²/S` não diz nada sozinho. A cena mostra as duas coisas que ele governa ao
 * mesmo tempo: **a planta da asa** (a envergadura e a corda que os sliders
 * ditam, com as cotas ao lado) e **o quanto o bicho plana** — porque o
 * alongamento é exatamente quantos metros a ave avança para cada metro que
 * desce.
 *
 * Asa curta e larga: AR baixo, a linha de planeio cai logo no mar. Longa e
 * estreita: AR alto, a linha quase não desce e o albatroz cruza o oceano.
 *
 * **A asa é uma PLANTA, não um retrato.** A primeira versão desenhava a ave
 * vista de cima, com curvas de bordo de ataque e de fuga; numa corda de sete
 * pixels — que é onde o slider a põe em boa parte da faixa — as curvas colapsam
 * e a silhueta vira um charuto escuro. A planta cotada continua legível em
 * qualquer proporção, e é ela que ensina a fórmula.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const MAR = '#2f6f9e';
const CORPO = '#5a657f';

const asa: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** A cota de uma medida: linha entre duas marcas, com o rótulo no meio. */
  function cota(
    ctx: CanvasRenderingContext2D,
    x0: number,
    x1: number,
    y: number,
    rotulo: string,
    tamanho: number,
  ): void {
    const cor = paleta();

    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(x0, y - 4);
    ctx.lineTo(x0, y + 4);
    ctx.moveTo(x1, y - 4);
    ctx.lineTo(x1, y + 4);
    ctx.moveTo(x0, y);
    ctx.lineTo(x1, y);
    ctx.stroke();

    etiqueta(ctx, rotulo, (x0 + x1) / 2, y, tamanho, cor.fraco, 700);
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const b = Math.max(0.1, numeroDe(valores, 'b', 5));
    const s = Math.max(0.1, numeroDe(valores, 's', 3));
    const alongamento = numeroDe(info, 'ar', (b * b) / s);
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : cor.azul;
    const miudo = limitar(A * 0.03, 8, 11);

    titulo(ctx, L, A, 'AR = b² ÷ S — metros à frente por metro de queda');

    // ── A planta da asa ───────────────────────────────────────────────────
    // Uma escala só para os dois eixos: é o que faz a asa longa PARECER longa.
    const escala = (L * 0.84) / 12;
    const envergadura = limitar(b * escala, 24, L * 0.88);
    const corda = limitar((s / b) * escala, 5, A * 0.14);
    const cyAsa = A * 0.26;

    // A área S, hachurada: é a superfície que sustenta, e o segundo slider.
    retangulo(
      ctx,
      L / 2 - envergadura / 2,
      cyAsa - corda / 2,
      envergadura,
      corda,
      Math.min(corda / 2, 8),
      tinta,
      cor.texto,
      1.2,
    );

    // O corpo, para a planta se ler como bicho e não como barra.
    ctx.fillStyle = CORPO;
    ctx.beginPath();
    ctx.ellipse(
      L / 2,
      cyAsa,
      Math.max(4, corda * 0.42),
      Math.max(10, corda * 1.5),
      0,
      0,
      Math.PI * 2,
    );
    ctx.fill();

    cota(
      ctx,
      L / 2 - envergadura / 2,
      L / 2 + envergadura / 2,
      cyAsa + Math.max(14, corda * 1.7),
      `b = ${b.toFixed(1).replace('.', ',')} m`,
      miudo,
    );
    texto(
      ctx,
      `S = ${s.toFixed(1).replace('.', ',')} m²`,
      L / 2 + envergadura / 2 + 4,
      cyAsa - Math.max(12, corda),
      miudo,
      { cor: cor.fraco, peso: 700, alinhamento: 'right' },
    );

    // ── O planeio ─────────────────────────────────────────────────────────
    const x0 = L * 0.07;
    const x1 = L * 0.93;
    const yPartida = A * 0.52;
    const yMar = A * 0.78;

    // O mar é uma FAIXA, não o resto do canvas: o rodapé mora em A·0,95, e
    // pintar até a borda deixava a leitura em cinza sobre azul-escuro.
    ctx.fillStyle = MAR;
    ctx.fillRect(0, yMar, L, A * 0.075);

    // Uma escala em que o alvo (AR 25) chega quase à borda: é a régua da cena.
    const alcance = (ar: number): number => limitar((ar / 28) * (x1 - x0), 0, x1 - x0);

    // A referência do alvo, atrás.
    ctx.strokeStyle = cor.ouro;
    ctx.lineWidth = 1.8;
    ctx.setLineDash([6, 4]);
    ctx.beginPath();
    ctx.moveTo(x0, yPartida);
    ctx.lineTo(x0 + alcance(25), yMar);
    ctx.stroke();
    ctx.setLineDash([]);
    etiqueta(
      ctx,
      'alvo AR 25',
      x0 + alcance(25),
      yPartida + (yMar - yPartida) * 0.28,
      miudo,
      cor.ouro,
      700,
      {
        alinhamento: 'right',
      },
    );

    // A linha do bicho.
    const xQueda = x0 + alcance(alongamento);
    ctx.strokeStyle = tinta;
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x0, yPartida);
    ctx.lineTo(xQueda, yMar);
    ctx.stroke();

    ctx.fillStyle = tinta;
    ctx.beginPath();
    ctx.arc(x0, yPartida, 4.5, 0, Math.PI * 2);
    ctx.fill();

    // Onde ele toca a água — o desfecho do planeio.
    ctx.fillStyle = 'rgb(255 255 255 / 80%)';
    ctx.beginPath();
    ctx.ellipse(xQueda, yMar + 2, 10, 3.4, 0, 0, Math.PI * 2);
    ctx.fill();

    etiqueta(
      ctx,
      `AR = ${alongamento.toFixed(1).replace('.', ',')}`,
      (x0 + xQueda) / 2,
      (yPartida + yMar) / 2,
      miudo * 1.1,
      tinta,
      800,
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'Planeio longo e plano ✔',
      alongamento < 25
        ? 'Asa curta e larga: cai logo no mar.'
        : 'Fina demais para sustentar o bicho.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default asa;
